def _map_keras_semantic_ops_binary_crossentropy(
    builder: TFToONNXGraphBuilder, node: TFNode
) -> list[str]:
    """Map Keras Semantic Ops Binary Crossentropy operation to ONNX equivalent."""
    if len(node.inputs) >= 2:
        sub = builder.make_node(
            "Sub", [node.inputs[0], node.inputs[1]], node.attr, node.name + "_sub"
        )[0]
        const_val = builder.make_node("Constant", [], {"value": 2.0}, node.name + "_c")[0]
        pow_node = builder.make_node("Pow", [sub, const_val], node.attr, node.name + "_pow")[0]
        return builder.make_node("ReduceMean", [pow_node], {"keepdims": 0}, node.name)
    if not node.inputs:
        return builder.make_node("Constant", [], {"value": 0.0}, node.name)
    return builder.make_node("ReduceMean", node.inputs, {"keepdims": 0}, node.name)


