def _map_keras_semantic_src_backend_torch_trainer_optimizers_module(
    builder: TFToONNXGraphBuilder, node: TFNode
) -> list[str]:
    """Map Keras Semantic Src Backend Torch Trainer Optimizers Module operation to ONNX equivalent."""
    if len(node.inputs) >= 2:
        lr = builder.make_node("Constant", [], {"value": 0.001}, node.name + "_lr")[0]
        step = builder.make_node("Mul", [node.inputs[1], lr], node.attr, node.name + "_step")[0]
        return builder.make_node("Sub", [node.inputs[0], step], node.attr, node.name)
    if not node.inputs:
        return builder.make_node("Constant", [], {"value": 0.0}, node.name)
    return builder.make_node("Identity", node.inputs, node.attr, node.name)


