def _map_keras_semantic_src_models_variable_mapping_metric(
    builder: TFToONNXGraphBuilder, node: TFNode
) -> list[str]:
    """Map Keras Semantic Src Models Variable Mapping Metric operation to ONNX equivalent."""
    if len(node.inputs) >= 2:
        eq = builder.make_node(
            "Equal", [node.inputs[0], node.inputs[1]], node.attr, node.name + "_eq"
        )[0]
        cast = builder.make_node("Cast", [eq], {"to": 1}, node.name + "_cast")[0]
        return builder.make_node("ReduceMean", [cast], {"keepdims": 0}, node.name)
    if not node.inputs:
        return builder.make_node("Constant", [], {"value": 0.0}, node.name)
    return builder.make_node("Cast", node.inputs, {"to": 1}, node.name)


def _map_keras_semantic_src_models_variable_mapping_optimizer(
    builder: TFToONNXGraphBuilder, node: TFNode
) -> list[str]:
    """Map Keras Semantic Src Models Variable Mapping Optimizer operation to ONNX equivalent."""
    if len(node.inputs) >= 2:
        lr = builder.make_node("Constant", [], {"value": 0.001}, node.name + "_lr")[0]
        step = builder.make_node("Mul", [node.inputs[1], lr], node.attr, node.name + "_step")[0]
        return builder.make_node("Sub", [node.inputs[0], step], node.attr, node.name)
    if not node.inputs:
        return builder.make_node("Constant", [], {"value": 0.0}, node.name)
    return builder.make_node("Identity", node.inputs, node.attr, node.name)


